import {writeDecisionGuides} from './decision-guides.mjs';
import {writeAcademicGuides} from './academic-guides.mjs';
import fs from 'node:fs';
import path from 'node:path';
import {iconifyHTML} from '../src/icons.mjs';
import {getCourseSpecs} from '../src/course-specs.mjs';
import {courses,areas,articles,events,services,faqs,portalNav} from '../src/data.mjs';
import {loadSchool,createBrand,paletteCss} from './school.mjs';
import {loadNavigation,loadHeader,loadFooter,loadSite,loadSimplePages,loadPageHeads,loadNotices,loadHome,loadInstitutionalPage,renderHeadline,renderInline} from './content.mjs';
const school=loadSchool();
// A validação em school.mjs recusa & < > " ' no nome, no país e na moeda:
// por isso um valor da configuração pode ser inserido depois de esc() sem reescapar.
const brand=createBrand(school);
const navigation=loadNavigation();
const site={header:loadHeader(),footer:loadFooter(),...loadSite()};
// Ênfase do conteúdo: *assim* → <em>assim</em>, sempre depois de esc(), e uma
// linha do conteúdo por quebra no título. O conteúdo nunca traz marcação.
const headline=value=>renderHeadline(value,esc);
// Toda a cadeia de navegação vem do conteúdo: rótulo, caminho interno validado
// e a seta de saída como sinalizador, não como texto escrito à mão.
const navAnchor=({url,label,external})=>`<a href="${esc(url)}">${esc(label)}${external?' ↗':''}</a>`;
const sigaPortal=school.portal;
const out='dist';fs.mkdirSync(out,{recursive:true});fs.cpSync('public',out,{recursive:true});fs.mkdirSync(out+'/integration',{recursive:true});fs.copyFileSync('integration/client.mjs',out+'/integration/client.mjs');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const logo=`<svg viewBox="0 0 36 36" aria-hidden="true"><path d="M5 12 18 5l13 7-13 7zM5 19l13 7 13-7M5 26l13 7 13-7"/></svg><span>{{SCHOOL}}<span class="brand-dot">.</span></span>`;
const link=(url,label,style='button')=>`<a class="${style}" href="${url}">${label}<span aria-hidden="true">↗</span></a>`;
const notice=(text=site.notice)=>`<div class="notice"><span aria-hidden="true">ⓘ</span><p>${text}</p></div>`;
const notices=loadNotices();
const noticeFor=key=>{const text=notices.get(key);if(!text)throw Error('Aviso em falta em content/notices.json: '+key);return esc(text)};
const crumb=(title,extra='')=>`<div class="breadcrumb wrap"><a href="/">${esc(site.breadcrumbHome)}</a><span>/</span>${extra}<span>${esc(title)}</span></div>`;
function menu({title,feature,links}){return `<details class="nav-dropdown"><summary>${esc(title)}<span>⌄</span></summary><div class="mega-menu"><div class="menu-highlight"><span class="eyebrow">O SEU PRÓXIMO PASSO</span><h3>${esc(feature.title)}</h3><p>${esc(feature.text)}</p>${link(esc(feature.url),esc(feature.label),'text-link')}</div><div class="mega-links">${links.map(({url,label,sub})=>`<a href="${esc(url)}"><strong>${esc(label)} <span>↗</span></strong><small>${esc(sub)}</small></a>`).join('')}</div></div></details>`}
function header(){const {skipLink,homeLabel,navLabel,menuLabel,topline,links,search,portal}=site.header;return `<a class="skip-link" href="#main">${esc(skipLink)}</a><div class="topline"><div class="wrap"><span>${esc(topline.identity)} <i></i> ${esc(topline.tagline)}</span><div>${topline.links.map(navAnchor).join('')}</div></div></div><header class="site-header"><div class="header-inner wrap"><a class="brand" href="/" aria-label="${esc(homeLabel)}">${logo}</a><button class="mobile-toggle icon-button" aria-expanded="false" aria-controls="main-nav" aria-label="${esc(menuLabel)}">☰</button><nav id="main-nav" aria-label="${esc(navLabel)}">${navigation.map(menu).join('')}${links.map(l=>`<a class="simple-nav" href="${esc(l.url)}">${esc(l.label)}</a>`).join('')}<div class="mobile-actions"><a href="${esc(portal.url)}">${esc(portal.mobileLabel)} ↗</a></div></nav><div class="header-actions"><a class="header-search" href="${esc(search.url)}" aria-label="${esc(search.label)}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/></svg></a><a class="button small" href="${esc(portal.url)}">${esc(portal.label)} <span>↗</span></a></div></div></header>`}
function footer(){const {tagline,locale,columns,notice,copyright,legal,backToTop}=site.footer;return `<footer class="site-footer"><div class="wrap"><div class="footer-main"><div><a class="brand" href="/">${logo}</a><p>${tagline.map(esc).join('<br>')}</p><span class="locale">◎ ${esc(locale)}</span></div>${columns.map(c=>`<div><h3>${esc(c.title)}</h3>${c.links.map(navAnchor).join('')}</div>`).join('')}</div><div class="footer-demo">${esc(notice)}</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${esc(copyright)}</span><div>${legal.map(navAnchor).join('')}</div><a href="#top">${esc(backToTop)} ↑</a></div></div></footer>`}
const routes=[];const searchContent=new Map();
function write(url,title,body,{portal=false,description,active=''}={}){const html=`<!doctype html><html lang="{{LANG}}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="${esc(school.themeColor)}"><meta name="description" content="${esc(description||title+' '+site.meta.descriptionSuffix)}"><title>${esc(title)} | ${esc(site.meta.titleSuffix)}</title><link rel="icon" href="/assets/icon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700&family=Manrope:wght@400;500;600;650;700;750;800&display=swap" rel="stylesheet"><link href="/style.css" rel="stylesheet"></head><body id="top" data-page="${esc(active||url)}" class="${portal?'portal-body':''}">${portal?'':header()}${portal?body:`<main id="main">${body}</main>${footer()}`}<div id="toast" role="status" aria-live="polite"></div><dialog id="site-dialog"><button class="dialog-close icon-button" aria-label="Fechar janela">×</button><div id="dialog-content"></div></dialog><script type="module" src="/app.js"></script></body></html>`;const dir=path.join(out,url);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),iconifyHTML(brand(html)));routes.push({url,title});searchContent.set(url,body.replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim().slice(0,12000))}
function pageHead(label,title,desc,extra=''){return `<section class="page-head"><div class="wrap"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p>${extra}</div><span class="head-spark" aria-hidden="true">✳</span></section>`}
// Cada página vai buscar o seu cabeçalho pela rota. Uma rota sem entrada no
// conteúdo pára o build: é a mesma regra das chaves em falta, ao nível da página.
const pageHeads=loadPageHeads();
const home=loadHome();
// Uma página institucional por ficheiro em content/pages/, validada pela forma
// declarada em content.mjs.
const pagina=name=>loadInstitutionalPage(name);
// Texto corrido: os parágrafos trazem ligações na convenção [rótulo](/caminho/),
// convertidas depois de esc(), e a lista de referências sai do mesmo bloco.
const prose=name=>{const page=pagina(name);write('/'+name+'/',page.title,`${crumb(page.crumb)}${head('/'+name+'/')}<article class="prose wrap section">${page.sections.map(s=>`<h2>${esc(s.title)}</h2>${s.paragraphs.map(t=>`<p>${renderInline(t,esc)}</p>`).join('')}${s.links?`<ul>${s.links.map(l=>`<li><a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)}</a>: ${esc(l.text)}</li>`).join('')}</ul>`:''}`).join('')}</article>`)};
// Os artigos em destaque de uma página são escolhidos pelo conteúdo: um id que
// não exista em data.mjs pára o build, em vez de desenhar uma grelha vazia.
const articleList=ids=>ids.map(id=>{const a=articles.find(x=>x.id===id);if(!a)throw Error('Artigo em falta em src/data.mjs: '+id);return a});
const head=(route,extra='')=>{const h=pageHeads.get(route);if(!h)throw Error('Página sem cabeçalho em content/page-heads.json: '+route);return pageHead(esc(h.eyebrow),headline(h.headline),esc(h.description),extra)};
function courseCard(c){const area=areas.find(a=>a.id===c.area);return `<article class="course-card" data-course="${c.id}"><div class="course-img ${area.color}"><a href="/cursos/${c.id}/" tabindex="-1" aria-hidden="true"><img src="/assets/${c.image}.webp" alt="" loading="lazy"></a><span class="pill">${c.level}</span><button class="favorite-button" data-favorite="${c.id}" aria-label="Guardar ${c.name} nos favoritos" aria-pressed="false">♡</button></div><div class="course-content"><span class="eyebrow course-area-label"><i class="area-dot ${area.color}"></i>${area.name}</span><h3><a href="/cursos/${c.id}/">${c.name}</a></h3><p>${c.description}</p><div class="course-meta"><span>◷ ${c.duration}</span><span>◎ ${c.mode}</span><span>☷ ${c.shift}</span></div><div class="course-actions"><a href="/cursos/${c.id}/">Conhecer o curso <span>↗</span></a><label><input type="checkbox" data-compare="${c.id}"> Comparar</label></div></div></article>`}
const searchBox=(id='hero-search')=>`<form class="course-search" action="/cursos/" id="${id}"><div><span aria-hidden="true">⌕</span><label class="sr-only" for="${id}-q">Nome ou área do curso</label><input id="${id}-q" name="q" placeholder="O que quer aprender?" type="search"></div><label class="sr-only" for="${id}-level">Nível de formação</label><select id="${id}-level" name="nivel"><option value="">Todas as formações</option><option>Licenciatura</option><option>Pós-graduação</option><option>Curso de curta duração</option></select><button class="button" type="submit">Encontrar curso <span>↗</span></button></form>`;
const cta=()=>`<section class="cta wrap reveal"><div><span class="eyebrow">${esc(site.cta.eyebrow)}</span><h2>${headline(site.cta.title)}</h2><p>${esc(site.cta.text)}</p></div><div>${link(esc(site.cta.primary.url),esc(site.cta.primary.label))}${link(esc(site.cta.secondary.url),esc(site.cta.secondary.label),'text-link')}</div><span class="cta-star" aria-hidden="true">✳</span></section>`;
write('/',home.title,`<section class="home-hero wrap"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> ${esc(home.hero.eyebrow)}</div><h1>${headline(home.hero.headline)}<span class="hero-arrow">↗</span></h1><p>${headline(home.hero.text)}</p><div class="hero-buttons">${link(esc(home.hero.primary.url),esc(home.hero.primary.label))}${link(esc(home.hero.secondary.url),esc(home.hero.secondary.label),'text-link')}</div><div class="hero-small"><span class="mini-symbol">✳</span><span>${headline(home.hero.small)}</span></div></div><div class="hero-visual"><div class="hero-grid"></div><div class="hero-photo"><img src="/assets/hero.webp" alt="${esc(home.hero.photoAlt)}" fetchpriority="high"><div class="hero-photo-caption">${esc(home.hero.photoCaption)} <span>↗</span></div></div><div class="hero-float"><span>✳</span><p>${headline(home.hero.float)}</p></div><div class="hero-badge"><i></i> ${esc(home.hero.badge)}</div><span class="hero-spark">✳</span><span class="hero-side">${esc(home.hero.side)}</span></div></section><section class="finder wrap"><div class="finder-title"><span class="eyebrow">${esc(home.finder.eyebrow)}</span>${navAnchor(home.finder.link)}</div>${searchBox()}<div class="finder-tags"><span>${esc(home.finder.tagsLabel)}</span>${home.finder.tags.map(navAnchor).join('')}</div></section><div class="marquee"><div>${[...home.marquee,...home.marquee].map(w=>`${esc(w)} <span>✳</span>`).join(' ')}</div></div><section class="quick-paths wrap" aria-label="${esc(home.quickPathsLabel)}">${home.quickPaths.map(p=>`<a href="${esc(p.url)}"><span>${esc(p.icon)}</span><div><strong>${esc(p.title)}</strong><small>${esc(p.text)}</small></div><b>↗</b></a>`).join('')}</section><section class="section wrap"><div class="section-title reveal"><div><span class="eyebrow">${esc(home.areas.eyebrow)}</span><h2>${headline(home.areas.headline)}</h2></div><p>${headline(home.areas.text)}</p></div><div class="areas-grid">${areas.map(a=>`<a class="area-card ${a.color} reveal" href="/cursos/?area=${a.id}"><span class="area-icon">${a.icon}</span><h3>${a.name}</h3><p>${a.description}</p><span class="area-bottom"><span>${courses.filter(c=>c.area===a.id).length} ${esc(home.areas.countLabel)}</span><span>↗</span></span></a>`).join('')}</div></section><section class="section soft-bg"><div class="wrap"><div class="section-title reveal"><div><span class="eyebrow">${esc(home.courses.eyebrow)}</span><h2>${headline(home.courses.headline)}</h2></div>${link(esc(home.courses.link.url),esc(home.courses.link.label),'text-link')}</div><div class="course-grid">${courses.filter(c=>c.featured).slice(0,3).map(courseCard).join('')}</div><p class="quiet-note">${esc(home.courses.note)}</p></div></section><section class="section wrap split-feature"><div class="split-photo reveal"><img src="/assets/student.webp" alt="${esc(home.split.photoAlt)}" loading="lazy"><span class="photo-label">${headline(home.split.photoLabel)} ↗</span></div><div class="reveal"><span class="eyebrow">${esc(home.split.eyebrow)}</span><h2>${headline(home.split.headline)}</h2><p>${esc(home.split.text)}</p><ul class="check-list">${home.split.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>${link(esc(home.split.link.url),esc(home.split.link.label),'text-link')}</div></section><section class="blue-band"><div class="wrap"><span class="eyebrow">${esc(home.band.eyebrow)}</span><h2>${renderHeadline(home.band.headline,esc,'span')}</h2><div class="steps-row">${home.band.steps.map(s=>`<div><span>${esc(s.number)}</span><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div>`).join('')}</div>${link(esc(home.band.action.url),esc(home.band.action.label),'button white')}<span class="band-star" aria-hidden="true">✳</span></div></section><section class="section wrap"><div class="section-title"><div><span class="eyebrow">${esc(home.articles.eyebrow)}</span><h2>${headline(home.articles.headline)}</h2></div>${link(esc(home.articles.link.url),esc(home.articles.link.label),'text-link')}</div><div class="article-grid">${articles.slice(0,3).map(articleCard).join('')}</div></section>${cta()}`);
function articleCard(a){return `<article class="article-card reveal"><a href="/noticias/${a.id}/" tabindex="-1" aria-hidden="true"><img src="/assets/${a.image}.webp" alt="" loading="lazy"></a><span class="eyebrow">${a.category} · LEITURA DEMONSTRATIVA</span><h3><a href="/noticias/${a.id}/">${a.title}</a></h3><a class="text-link" href="/noticias/${a.id}/">Ler a história <span>↗</span></a></article>`}
const catalogo=pagina('cursos');
// Os valores das opções (Licenciatura, Presencial, Diurno…) continuam aqui: têm
// de bater certo com os campos dos cursos em data.mjs e com a filtragem do app.js.
// O que é texto — os rótulos — vem do conteúdo.
const filters=`<aside class="filters" id="course-filters"><div class="filter-title"><h2>${esc(catalogo.filters.title)}</h2><button type="button" id="clear-filters">${esc(catalogo.filters.clear)}</button></div><label>${esc(catalogo.filters.area.label)}<select name="area" id="filter-area"><option value="">${esc(catalogo.filters.area.all)}</option>${areas.map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></label><label>${esc(catalogo.filters.level.label)}<select name="nivel" id="filter-level"><option value="">${esc(catalogo.filters.level.all)}</option><option>Licenciatura</option><option>Pós-graduação</option><option>Curso de curta duração</option></select></label><fieldset><legend>${esc(catalogo.filters.mode.label)}</legend>${['Presencial','Online','Híbrido'].map(m=>`<label class="check-option"><input type="checkbox" name="mode" value="${m}">${m}</label>`).join('')}</fieldset><label>${esc(catalogo.filters.shift.label)}<select name="turno" id="filter-shift"><option value="">${esc(catalogo.filters.shift.all)}</option><option>Diurno</option><option>Pós-laboral</option><option>Flexível</option></select></label><label>${esc(catalogo.filters.unit.label)}<select name="unidade" id="filter-unit"><option value="">${esc(catalogo.filters.unit.all)}</option><option>Campus Académico</option><option>Campus Digital</option></select></label><div class="filter-help"><span>${esc(catalogo.filters.help.title)}</span><p>${esc(catalogo.filters.help.text)}</p>${navAnchor(catalogo.filters.help.link)}</div></aside>`;
write('/cursos/',catalogo.title,`${crumb(catalogo.crumb)}${head('/cursos/')}<section class="wrap catalogue-section"><div class="catalogue-top"><form id="catalog-search" class="search-input"><span>⌕</span><label class="sr-only" for="catalog-q">${esc(catalogo.search.label)}</label><input type="search" id="catalog-q" placeholder="${esc(catalogo.search.placeholder)}"><button class="button small">${esc(catalogo.search.button)}</button></form><a href="/favoritos/" class="outline-button">${esc(catalogo.favourites.icon)} ${esc(catalogo.favourites.label)} <span data-favorite-count>0</span></a><a href="/comparar/" class="outline-button">${esc(catalogo.compare.icon)} ${esc(catalogo.compare.label)} <span data-compare-count>0</span></a></div>${notice()}<div class="catalogue-mobile-tools"><button class="outline-button" id="toggle-filters" aria-expanded="false" aria-controls="course-filters"><span>${esc(catalogo.mobileFilters.icon)}</span> ${esc(catalogo.mobileFilters.label)} <b id="mobile-filter-count" hidden>0</b><span class="filter-chevron">⌄</span></button><span>${esc(catalogo.mobileFilters.hint)}</span></div><div class="catalogue-layout">${filters}<div class="catalogue-results"><div class="results-heading"><p id="results-count" aria-live="polite">${courses.length} ${esc(catalogo.countLabel)}</p><label>${esc(catalogo.sort.label)} <select id="sort-courses"><option value="featured">${esc(catalogo.sort.featured)}</option><option value="az">${esc(catalogo.sort.az)}</option><option value="duration">${esc(catalogo.sort.duration)}</option></select></label></div><div id="active-filters"></div><div class="course-grid two-cols" id="course-results">${courses.map(courseCard).join('')}</div><div id="no-courses" class="empty-state" hidden><span>${esc(catalogo.empty.icon)}</span><h2>${esc(catalogo.empty.title)}</h2><p>${esc(catalogo.empty.text)}</p><button class="button" id="empty-clear">${esc(catalogo.empty.button)} <span>↗</span></button></div></div></div></section><div id="compare-bar" class="compare-bar" hidden><span><strong data-compare-count>0</strong> ${esc(catalogo.compareBar.text)}</span><a class="button small" href="/comparar/">${esc(catalogo.compareBar.button)} ↗</a></div>`,{active:'catalog'});
const curso=pagina('curso');
// Os valores do curso entram no conteúdo por marcador — {{COURSE}}, {{LEVEL}},
// {{ACCESS}}… — e `ce` é o esc() do curso: escapa o texto e, a seguir, escapa
// também o valor que substitui o marcador.
const cursoTokens=(c,specs)=>({COURSE:c.name,DESCRIPTION:c.description,LEVEL:c.level,DURATION:c.duration,MODE:c.mode,SHIFT:c.shift,UNIT:c.unit,STRUCTURE:specs.structure,LANGUAGE:specs.language,DELIVERY:specs.delivery,PRACTICE:specs.practice,ASSESSMENT:specs.assessment,RESOURCES:specs.resources,ACCESS:specs.access});
const cursoEsc=tokens=>s=>esc(s).replace(/\{\{([A-Z_]{2,32})\}\}/g,(match,key)=>key in tokens?esc(tokens[key]):match);
for(const c of courses){const area=areas.find(a=>a.id===c.area);const specs=getCourseSpecs(c);const ce=cursoEsc(cursoTokens(c,specs));write('/cursos/'+c.id+'/',c.name,`${crumb(c.name,`<a href="/cursos/">${esc(catalogo.crumb)}</a><span>/</span>`)}<section class="course-hero wrap"><div><div class="eyebrow">${area.name} · ${c.level}</div><h1>${c.name}</h1><p>${c.description}</p><div class="course-hero-meta"><span>◷ ${c.duration}</span><span>◎ ${c.mode}</span><span>☷ ${c.shift}</span></div><div class="course-code">${ce(curso.hero.codeLabel)} <span>•</span> ${c.level} <span>•</span> ${area.name}</div><div class="hero-buttons">${link('/candidatura/?curso='+c.id,ce(curso.hero.apply.label))}<button class="outline-button" data-favorite="${c.id}" aria-pressed="false">${ce(curso.hero.save.icon)} ${ce(curso.hero.save.label)}</button></div><p class="quiet-note">${ce(curso.hero.note)}</p></div><div class="course-hero-image"><img src="/assets/${c.image}.webp" alt="${ce(curso.hero.photoAlt)}" fetchpriority="high"><span>${area.icon}</span></div></section><nav class="course-subnav" aria-label="${ce(curso.subnav.label)}"><div class="wrap">${curso.subnav.items.map(x=>`<a href="#${ce(x.anchor)}">${ce(x.label)}</a>`).join('')}</div></nav><section class="section wrap course-detail-layout"><div><section id="apresentacao" class="detail-block"><span class="eyebrow">${ce(curso.presentation.eyebrow)}</span><h2>${renderHeadline(curso.presentation.headline,ce)}</h2>${curso.presentation.paragraphs.map(t=>`<p>${ce(t)}</p>`).join('')}${notice(noticeFor('curso'))}</section><section id="competencias" class="detail-block course-competencies"><span class="eyebrow">${ce(curso.skills.eyebrow)}</span><h2>${ce(curso.skills.title)}</h2><p>${ce(curso.skills.text)}</p><ul class="competency-list">${specs.outcomes.map((item,i)=>`<li><span>0${i+1}</span><p>${item}</p><b aria-hidden="true">↗</b></li>`).join('')}</ul><div class="course-audience"><h3>${ce(curso.skills.audienceTitle)}</h3><p>${specs.audience}</p><span>${ce(curso.skills.startLabel)}</span><p>${specs.preparation}</p></div></section><section id="plano" class="detail-block"><span class="eyebrow">${ce(curso.plan.eyebrow)}</span><h2>${ce(curso.plan.title)}</h2><p>${ce(curso.plan.text)}</p><div class="module-list">${c.modules.map((m,i)=>`<details${i===0?' open':''}><summary><span>0${i+1}</span>${m}<b>+</b></summary><p>${specs.modules[i].description}</p><span class="module-caption">${ce(curso.plan.moduleCaption)}</span></details>`).join('')}</div></section><section class="detail-block course-method"><span class="eyebrow">${ce(curso.method.eyebrow)}</span><h2>${ce(curso.method.title)}</h2><div class="method-grid">${curso.method.cards.map(x=>`<article><span>${ce(x.icon)}</span><h3>${ce(x.title)}</h3><p>${ce(x.text)}</p></article>`).join('')}</div><details class="resource-details"><summary>${ce(curso.method.resources.summary)} <span>+</span></summary><p>${ce(curso.method.resources.text)}</p><a class="text-link" href="${ce(curso.method.resources.link.url)}">${ce(curso.method.resources.link.label)} ↗</a></details></section><section id="carreiras" class="detail-block"><span class="eyebrow">${ce(curso.careers.eyebrow)}</span><h2>${ce(curso.careers.title)}</h2><p>${ce(curso.careers.text)}</p><div class="career-tags">${c.careers.map(x=>`<span>↗ ${x}</span>`).join('')}</div></section><section id="ingresso" class="detail-block"><h2>${ce(curso.entry.title)}</h2><p>${ce(curso.entry.text)}</p>${link(ce(curso.entry.link.url),ce(curso.entry.link.label),'text-link')}<div class="entry-requirement"><span>${ce(curso.entry.requirement.icon)}</span><div><h3>${ce(curso.entry.requirement.title)}</h3><p>${ce(curso.entry.requirement.text)}</p></div></div></section><section class="detail-block course-questions"><h2>${ce(curso.questions.title)}</h2><div class="faq-list">${curso.questions.items.map(q=>`<details><summary>${ce(q.question)}<span>+</span></summary><p>${ce(q.answer)}</p></details>`).join('')}</div></section></div><aside class="course-summary"><span class="eyebrow">${ce(curso.summary.eyebrow)}</span><h3>${c.name}</h3><dl>${curso.summary.fields.map(f=>`<div><dt>${ce(f.label)}</dt><dd>${ce(f.value)}</dd></div>`).join('')}</dl>${link('/candidatura/?curso='+c.id,ce(curso.summary.apply))}<button class="course-guide-button outline-button" data-course-guide="${c.id}">${ce(curso.summary.guide)} <span>↓</span></button><label class="compare-label"><input type="checkbox" data-compare="${c.id}"> ${ce(curso.summary.compare)}</label><a href="${ce(curso.summary.contact.url)}">${ce(curso.summary.contact.label)}${curso.summary.contact.external?' ↗':''}</a></aside></section><aside class="course-mobile-action" data-course-action hidden aria-label="${ce(curso.mobile.label)}"><div><small>${ce(curso.mobile.tag)}</small><strong>${c.name}</strong></div>${link('/candidatura/?curso='+c.id,ce(curso.mobile.button),'button small')}</aside><section class="section soft-bg"><div class="wrap"><div class="section-title"><div><span class="eyebrow">${ce(curso.related.eyebrow)}</span><h2>${ce(curso.related.title)}</h2></div>${link(ce(curso.related.link.url),ce(curso.related.link.label),'text-link')}</div><div class="course-grid">${courses.filter(x=>x.id!==c.id).sort((a,b)=>Number(b.area===c.area)-Number(a.area===c.area)).slice(0,3).map(courseCard).join('')}</div></div></section>`,{active:'course'})}
