const candidatura=pagina('candidatura');
// Os nomes dos campos são lidos pelo app.js: ficam aqui. O que se lê — rótulos,
// marcadores, as províncias — é conteúdo, e o número de confirmações tem de
// corresponder aos campos que o formulário guarda.
