write('/candidatura/',candidatura.title,`${crumb(candidatura.crumb)}${head('/candidatura/')}<section class="wrap section application-layout"><aside class="application-aside"><span class="eyebrow">${esc(candidatura.aside.eyebrow)}</span><ol class="wizard-steps">${candidatura.aside.steps.map((s,i)=>`<li${i===0?' class="current"':''} data-step-label="${esc(s.number)}"><span>${esc(s.number)}</span><div><strong>${esc(s.title)}</strong><small>${esc(s.text)}</small></div></li>`).join('')}</ol><div class="application-help"><h3>${esc(candidatura.aside.help.title)}</h3><p>${esc(candidatura.aside.help.text)}</p>${navAnchor(candidatura.aside.help.link)}</div></aside><div class="application-form"><div class="wizard-progress" aria-hidden="true"><span id="wizard-progress-bar"></span></div>${notice(noticeFor('candidatura'))}<div id="draft-prompt" hidden></div><form id="application-form"><section data-step="1"><div class="step-heading"><span class="eyebrow">${esc(candidatura.step1.eyebrow)}</span><h2>${esc(candidatura.step1.title)}</h2><p>${esc(candidatura.step1.text)}</p></div><label>${esc(candidatura.step1.course.label)} <span>*</span><select id="apply-course" name="course" required><option value="">${esc(candidatura.step1.course.placeholder)}</option>${courses.map(c=>`<option value="${c.id}">${c.name} · ${c.level}</option>`).join('')}</select></label><div id="apply-course-info"></div><div class="form-row"><label>${esc(candidatura.step1.via.label)} <span>*</span><select name="via" required><option value="">${esc(candidatura.step1.via.placeholder)}</option>${candidatura.step1.via.options.map(o=>`<option>${esc(o)}</option>`).join('')}</select></label><label>${esc(candidatura.step1.period.label)} <span>*</span><select name="period" required><option value="">${esc(candidatura.step1.period.placeholder)}</option>${candidatura.step1.period.options.map(o=>`<option>${esc(o)}</option>`).join('')}</select></label></div></section><section data-step="2" hidden><div class="step-heading"><span class="eyebrow">${esc(candidatura.step2.eyebrow)}</span><h2>${esc(candidatura.step2.title)}</h2><p>${esc(candidatura.step2.text)}</p></div><label>${esc(candidatura.step2.name.label)} <span>*</span><input name="name" required maxlength="100" autocomplete="off" placeholder="${esc(candidatura.step2.name.placeholder)}"></label><div class="form-row"><label>${esc(candidatura.step2.email.label)} <span>*</span><input name="email" type="email" required maxlength="150" autocomplete="off" placeholder="${esc(candidatura.step2.email.placeholder)}"></label><label>${esc(candidatura.step2.province.label)} <span>*</span><select name="province" required><option value="">${esc(candidatura.step2.province.placeholder)}</option>${candidatura.step2.province.options.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label></div><label>${esc(candidatura.step2.motivation.label)}<textarea name="motivation" maxlength="1000" rows="4" placeholder="${esc(candidatura.step2.motivation.placeholder)}"></textarea></label><div class="checklist-box"><h3>${esc(candidatura.step2.checklist.title)}</h3><p>${esc(candidatura.step2.checklist.text)}</p>${candidatura.step2.checklist.items.map((t,i)=>`<label class="check-option"><input type="checkbox" name="${CONFIRMACOES[i]}"> ${esc(t)}</label>`).join('')}</div></section><section data-step="3" hidden><div class="step-heading"><span class="eyebrow">${esc(candidatura.step3.eyebrow)}</span><h2>${esc(candidatura.step3.title)}</h2><p>${esc(candidatura.step3.text)}</p></div><div id="application-review" class="review-card"></div><label class="check-option consent"><input type="checkbox" name="consent" required> ${esc(candidatura.step3.consent)}</label></section><p id="application-error" class="form-error" role="alert"></p><div class="form-controls"><button type="button" class="text-button" id="wizard-back" hidden>← ${esc(candidatura.controls.back)}</button><button type="button" class="text-button" id="save-draft">${esc(candidatura.controls.draft)}</button><button type="submit" class="button" id="wizard-next">${esc(candidatura.controls.next)} <span>→</span></button></div></form><div id="application-success" hidden class="success-panel"></div></div></section>`,{active:'application'});
