function portalShell(key,title,body){return `<a class="skip-link" href="#main">Saltar para o conteúdo</a><aside class="portal-sidebar"><a class="brand" href="/">${logo}</a><span class="portal-label">PORTAL ACADÉMICO</span><nav aria-label="Menu do portal">${portalNav.map(([id,label,icon])=>`<a class="${id===key?'active':''}" href="/portal/${id?id+'/':''}"><span>${icon}</span>${label}${id===key?'<b>•</b>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="/ajuda/">ⓘ Central de ajuda ↗</a><a href="/">↗ Voltar ao website</a><a href="/signout-with-chatgpt?return_to=%2Flogin%2F" target="_top">⇥ Terminar sessão</a></div><div class="sidebar-profile"><span>JE</span><div><strong>Joana Exemplo</strong><small>Perfil demonstrativo</small></div><a href="/portal/perfil/" aria-label="Ver perfil">⌄</a></div></aside><div class="portal-main"><header class="portal-header"><button class="portal-menu icon-button" aria-label="Abrir menu do portal" aria-expanded="false">☰</button><div><span>O SEU ESPAÇO ACADÉMICO</span><p>${title}</p></div><div class="portal-header-right"><a href="/pesquisa/" aria-label="Pesquisar">⌕</a><button class="icon-button" id="portal-notifications" aria-label="Ver avisos demonstrativos">♧<i></i></button><span class="profile-small">JE</span></div></header><div class="demo-strip"><span>◉ Modo de demonstração</span><p>Perfil e dados fictícios · Sem ligação ao sistema académico</p><a href="/sobre-o-projecto/">Saiba mais ↗</a></div><main id="main" class="portal-content"><div class="portal-page-title"><div><div class="eyebrow">{{SCHOOL}} / PORTAL ACADÉMICO</div><h1>${title}</h1></div><span class="semester-pill">2026 / 2027 · Exemplo</span></div>${body}</main><footer class="portal-footer"><span>{{SCHOOL}} · Portal demonstrativo</span><a href="/privacidade/">Dados guardados apenas neste navegador ↗</a></footer></div>`}
